#!/usr/bin/env python3
"""Render three independent articles from validated raw campaign files."""
import html,json,shutil,statistics,re
from pathlib import Path
from plot_startup import draw_shell_plot, draw_comparison, draw_corpus_scaling
ROOT=Path(__file__).resolve().parents[1];DATA=ROOT/'content/benchmarks/data'
esc=lambda x:html.escape(str(x))
def f(x):return f'{x:,.3f}' if x<100 else f'{x:,.1f}'
def load(name):
 d=json.loads((DATA/name).read_text());assert d['publishable'] and d['jobs']
 for j in d['jobs']:
  assert all(r['correct'] for r in j['samples'])
  rows=[r for r in j['samples'] if not r['warmup']]
  assert len(rows)==j['summary']['samples']
  assert statistics.median(r['wall_ms'] for r in rows)==j['summary']['median_ms']
 return d
def active_path(slug,name):
 meta=series_meta(slug)
 return DATA/'history'/meta['series']/slug/name if meta else DATA/name
def load_active(slug,name):
 return load(str(active_path(slug,name).relative_to(DATA)))
def raw_active(slug,name):
 return json.loads(active_path(slug,name).read_text())
def table(headers,rows,caption):
 numeric=[i>0 and any(re.fullmatch(r'[0-9.,–−]+',str(row[i])) for row in rows) and all(re.fullmatch(r'[0-9.,–−]+',str(row[i])) or row[i] in ('Outside scope','—') for row in rows) for i in range(len(headers))]
 return '<div class="table-scroll" role="region" tabindex="0" aria-label="'+esc(caption)+'"><table><caption>'+esc(caption)+'</caption><thead><tr>'+''.join(('<th scope="col" class="num">' if numeric[i] else '<th scope="col">')+esc(h)+'</th>' for i,h in enumerate(headers))+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">' if i==0 else ('<td class="num">' if numeric[i] else '<td>'))+('<span class="scope-marker" aria-label="Outside scope" title="Outside scope">—</span>' if c=='Outside scope' else esc(c))+('</th>' if i==0 else '</td>') for i,c in enumerate(row))+'</tr>' for row in rows)+'</tbody></table></div>'
def figure(slug,key,labels,series,title,unit,log=False):
 draw_comparison(labels,series,ROOT/f'public/benchmarks/{slug}/assets/{key}.svg',title,unit,slug,log)
 return '<figure class="benchmark-figure"><div class="chart-scroll" role="region" tabindex="0" aria-label="'+esc(title)+'"><img src="@path(\'public/benchmarks/'+slug+'/assets/'+key+'.svg\')" alt="'+esc(title+'. '+unit+('. Logarithmic axis.' if log else '. Zero-based axis.'))+'"></div><figcaption>'+esc(title)+('. Logarithmic scale; bar lengths are not proportional to values.' if log else '. Zero-based scale.')+' <a href="@path(\'public/benchmarks/'+slug+'/assets/'+key+'.svg\')">SVG</a> · <a href="@path(\'public/benchmarks/'+slug+'/assets/'+key+'.png\')">PNG</a>. Exact values appear in the accompanying tables.</figcaption></figure>'
def section(label,title,body,id=None):return '<section class="section"'+(' id="'+id+'"' if id else '')+'><p class="eyebrow">'+label+'</p><h2>'+title+'</h2>'+body+'</section>'
def p(text):return '<p>'+text+'</p>'
def related(slug):
 names={'scripting':'Scripting Benchmark','website-generator':'Website Generator Benchmark','shell':'Shell Benchmark'}
 return section('Nift Benchmarks','Three perspectives on one runtime.','<nav class="related" aria-label="Related reports">'+''.join(f'<a href="@path(\'benchmarks/{s}/\')">{n} ↗</a>' for s,n in names.items() if s!=slug)+'</nav>')
def series_meta(slug):
 path=DATA/'series.json'
 return json.loads(path.read_text()).get(slug) if path.exists() else None
def series_notice(slug):
 meta=series_meta(slug)
 if not meta:return ''
 base=f'public/benchmarks/{slug}/evidence/{meta["series"]}'
 return p(f'Series <strong>{esc(meta["series"])}</strong> · measured {esc(meta["date_local"])}. Nift <strong>{esc(meta["nift_version"])}</strong> is a release-preparation build, built from <a href="https://github.com/nift-dev/nift/tree/{meta["nift_revision"]}">this frozen source revision</a>. <a href="@path(\'public/benchmarks/{slug}/series/20261008-v480/index.html\')">The frozen v4.8 report and original figures</a>, <a href="@path(\'public/benchmarks/{slug}/evidence/20261008-v480/README.md\')">its complete raw evidence</a> and the <a href="@path(\'public/benchmarks/{slug}/evidence/20261007-v472/README.md\')">earlier v4.7.2 series</a> remain available. Separate nodes may have different virtual CPUs; cross-node deltas cannot be attributed entirely to Nift. <a href="@path(\'{base}/run-identity.json\')">Run identity and build provenance</a>. <a href="@path(\'public/benchmarks/evidence/campaign-20261009-v490.md\')">Campaign report and lifecycle</a>.')
def machine(d,slug=None):
 m=d['machine'];cpu=next((x.split(':',1)[1].strip() for x in m['cpuinfo'].splitlines() if x.startswith('model name')),'Unknown')
 osname=next((x.split('=',1)[1].strip('"') for x in m['os_release'].splitlines() if x.startswith('PRETTY_NAME=')),'Linux')
 cards='<div class="spec"><div><small>Linode / us-east</small><strong>8 GB · 4 vCPU</strong><p>g6-standard-4, shared CPU; all measured processes pinned to CPU 0.</p></div><div><small>Processor</small><strong>'+esc(cpu)+'</strong><p>Virtual scheduling and neighbouring tenants may affect latency.</p></div><div><small>System</small><strong>'+esc(osname)+'</strong><p>Kernel '+esc(m['kernel'])+'; Python '+esc(m['python'])+'.</p></div></div>'
 cards+=p(f"""Tool/fixture preparation was outside timing. OS caches were uncontrolled. State-reset scope is suite-specific; no machine-cold boot is claimed. Suite revision: <code>{esc(m['revision'])}</code>. Raw evidence records CPU/RAM inventory, binary hashes and exact commands. <a href="@path('public/benchmarks/evidence/provisioning.json')">Provisioning and verified teardown record</a>. <a href="@path('public/benchmarks/evidence/system-startup-files.json')">System startup-file hashes</a> and <a href="@path('public/benchmarks/evidence/dpkg-versions.tsv')">distro package versions</a> support reproduction. <a href="@path('public/benchmarks/evidence/diagnostics.tar.gz')">Superseded series archive</a> and <a href="@path('public/benchmarks/evidence/README.md')">evidence notes</a> retain the earlier PTY method, website pins and scripting corpus; these are excluded from the official summaries.""")
 meta=series_meta(slug)
 if meta:
  base=f'public/benchmarks/{slug}/evidence/{meta["series"]}'
  cards=cards[:cards.index('<p>Tool/fixture preparation')]+p(f'Tool/fixture preparation was outside timing. OS caches were uncontrolled; no machine-cold boot is claimed. Exact suite revision: <code>{esc(m["revision"])}</code>. <a href="@path(\'{base}/node-specifications.json\')">Linode plan and provisioning record</a>; <a href="@path(\'{base}/teardown.json\')">Teardown status and verification record</a>. <a href="@path(\'{base}/system-startup-files.json\')">System startup-file hashes</a>, <a href="@path(\'{base}/dpkg-versions.tsv\')">distro/compiler package versions</a>, <a href="@path(\'{base}/filesystem.json\')">filesystem</a>, <a href="@path(\'{base}/storage.json\')">storage inventory</a> and <a href="@path(\'{base}/machine-extra.json\')">frequency/governor and cgroup information</a> describe this specific node. Raw observations retain CPU/RAM inventory, binary hashes and exact commands. Historical nodes are separate series.')
 rows=[]
 for name,v in d['tools'].items():rows.append([name,v['version'].splitlines()[0] if isinstance(v,dict) else v])
 return section('Frozen environment','One node. One logical CPU.',cards,'machine')+section('Versions','Tested systems',table(['System','Measured version'],rows,'Detected on the measurement node'))
def evidence(slug,files,repo,cmd):
 out=ROOT/'public/benchmarks'/slug/'evidence';out.mkdir(parents=True,exist_ok=True)
 meta=series_meta(slug)
 if not meta:
  for fn in files:shutil.copyfile(DATA/fn,out/fn)
 else:
  for fn in files:assert (out/meta['series']/fn).read_bytes()==active_path(slug,fn).read_bytes()
 branch='main' if repo=='shell-benchmark' else 'stage'
 revision=raw_active(slug,files[0])['machine']['revision']
 clean={'shell':'shell','scripting':'scripting','website-generator':'website'}[slug]
 meta=series_meta(slug)
 base=f'public/benchmarks/{slug}/evidence'+('/'+meta['series'] if meta else '')
 links=' · '.join(f'<a href="@path(\'{base}/{fn}\')">{fn}</a>' for fn in files)
 smoke_file='smoke-shell-repeated.json' if slug=='shell' else 'smoke-scripting.json'
 clean_link=f'{base}/{smoke_file}' if meta else f'public/benchmarks/evidence/clean-checkout-{clean}.json'

 return section('Reproduce / scrutinise','Every sample is retained.',p(links)+(p(f'Clean-checkout validation on the measurement node: <a href="@path(\'{clean_link}\')">complete smoke run</a>.') if meta else p(f'Independent clean-checkout reproduction: <a href="@path(\'{clean_link}\')">validated raw run</a>.'))+p(f'<a href="https://github.com/nift-dev/{repo}/tree/{branch}">Suite, audit and provisioning instructions ↗</a>. Check out the <a href="https://github.com/nift-dev/{repo}/tree/{revision}">exact measured suite revision</a> and acquire its pinned tools. <code>scripts/summarize.py</code> regenerates summaries from one validated run; historical machines and revisions are never merged.')+'<pre>'+esc(cmd)+'</pre>'+p('Warmups are retained separately. Correctness failures/timeouts stop publication. Corrected observations are all retained; superseded method, tool-pin and workload series are archived as diagnostics with reasons for exclusion. Percentiles use linear interpolation and describe this sample distribution; they are not confidence intervals.'),'reproduce')
def write(slug,text):
 nav='<nav class="section-nav" aria-label="Report sections"><a href="#results">Results</a><a href="#method">Method</a><a href="#machine">Machine</a><a href="#reproduce">Evidence</a></nav>'
 text=text.replace('</section>','</section>'+series_notice(slug)+nav,1)
 (ROOT/f'content/benchmarks/{slug}/index.html').write_text('<main id="main">'+text+related(slug)+'</main>')
def shell():
 d=load_active('shell','shell-repeated.json');c=load_active('shell','shell-application-cold.json');by={j['id']:j for j in d['jobs']};cold={j['id']:j for j in c['jobs']};names=('bash','zsh','fish','nu','nift')
 def r(s,sc='bare',metric='interactive'):return by[f'{s}/{sc}/{metric}']['summary']
 hero='<section class="hero"><p class="eyebrow">Experiment 03 / startup &amp; shells</p><h1>How long until<br><span>the prompt is ready?</span> <i class="cursor" aria-hidden="true"></i></h1>'+p('Every invocation pays a startup cost. We measured Bash, Zsh, Fish, Nushell and Nift, made RC work explicit, and kept the stalls visible.')+'<div class="boot" aria-label="Conceptual startup sequence"><div><small>01 / timed boundary</small><b>Process starts</b></div><div><small>02 / conceptual phase</small><b>Runtime initialises</b></div><div><small>03 / explicit variable</small><b>RC loads</b></div><div><small>04 / PTY boundary</small><b>Prompt ready</b></div></div>'+p('Stages explain the model; individual stage durations were not measured. Only the total startup boundary is timed.')+'</section>'
 draw_shell_plot(d,ROOT/'public/benchmarks/shell/assets/startup-distributions.svg')
 svg='<img src="@path(\'public/benchmarks/shell/assets/startup-distributions.svg\')" alt="Bare first-prompt latency distributions: lines are min–max, circles medians and diamonds p95, with a zero-based millisecond axis. Exact observations follow in the table.">'
 rows=[[s,f(r(s,metric='immediate-exit')['median_ms']),f(r(s,metric='trivial-command')['median_ms']),f(r(s)['median_ms']),f(r(s)['p95_ms']),f(r(s)['p99_ms'])] for s in names]
 result='<div class="chart-scroll" role="region" tabindex="0" aria-label="Bare prompt distributions">'+svg+'</div>'+table(['Shell','Exit ms','Trivial ms','Prompt ms','Prompt p95','Prompt p99'],rows,'Bare prepared state; 100 measured samples per startup cell')
 result+=p('Bash’s bare prompt median was '+f(r('bash')['median_ms'])+' ms and Zsh’s was '+f(r('zsh')['median_ms'])+' ms. Their p99 values were '+f(r('bash')['p99_ms'])+' and '+f(r('zsh')['p99_ms'])+' ms; Nift’s was '+f(r('nift')['p99_ms'])+' ms. Tails remain visible even where medians are small.')
 result+=p('<a href="@path(\'public/benchmarks/shell/assets/startup-distributions.svg\')">Download the SVG figure</a> · <a href="@path(\'public/benchmarks/shell/assets/startup-distributions.png\')">PNG figure</a>.')
 result+=p('Exit/trivial use C-supervised non-interactive command evaluation. Prompt startup uses a real controlling PTY, excludes Python/bridge launch but includes PTY forwarding and minimal xterm query handling, then validates RC state. Those boundaries differ; subtracting them would not recover RC cost.')
 result+=f'<div class="callout"><strong>Observed:</strong> Nift’s trivial bare invocation median was {f(r("nift",metric="trivial-command")["median_ms"])} ms; Bash’s was {f(r("bash",metric="trivial-command")["median_ms"])} ms. This describes this exact node and invocation, not overall shell quality.</div>'
 rc='<div class="scope"><div><b>Bare</b>No user config.</div><div><b>Empty</b>Normal path; empty files.</div><div><b>Light</b>8 environment values + functions.</div><div><b>Moderate</b>32 values + functions.</div></div>'+p('Light/moderate also prepend one PATH entry and perform a HOME-existence conditional. A post-prompt oracle validates representative environment, function and conditional state. No aliases or plugin managers are forced onto shells without equivalent facilities.')
 for source,label in ((by,'Prepared state, non-login'),(cold,'Fresh HOME/XDG per invocation, non-login')):
  rows=[[s]+[f(source[f'{s}/{sc}/interactive']['summary']['median_ms']) for sc in ('bare','empty','light','moderate')] for s in names]
  rc+=table(['Shell','Bare ms','Empty ms','Light ms','Moderate ms'],rows,label+f'; medians, {d["samples"] if source is by else c["samples"]} measured samples per cell')
 rows=[[s]+[f(r(s,sc,'interactive-login')['median_ms']) for sc in ('bare','empty','light','moderate')] for s in names[:-1]]
 rc+=figure('shell','rc-prepared',names,{sc:[r(n,sc)['median_ms'] for n in names] for sc in ('bare','empty','light','moderate')},'Prepared first-prompt startup','Median latency (ms)')
 rc+='<details><summary>Login matrix</summary>'+table(['Shell','Bare ms','Empty ms','Light ms','Moderate ms'],rows,'Login prompt startup; Nift has no separate login mode')+'</details>'
 rc+=p('Fresh configured Zsh medians were '+f(cold['zsh/empty/interactive']['summary']['median_ms'])+' ms for empty user files and '+f(cold['zsh/moderate/interactive']['summary']['median_ms'])+' ms for moderate files. Ubuntu’s normal system completion setup rebuilds per fresh HOME; the normal-path matrix includes that work.')
 rc+=p('Bare means no <em>user</em> config. Zsh still reads compiled system zshenv. Normal/login paths retain distro-wide configuration. Nift uses isolated HOME because there is no no-RC option; Nu keeps its standard library. Direct startup measurements are never derived by subtracting RC time. Fresh application directories reset config/cache/history state without flushing OS caches.')
 rows=[[key]+[f(r(s,metric=key)['median_ms']) for s in names] for key in ('native-sum','function-string','external-100','short-pipeline','command-capture','file-roundtrip')]
 work=table(['Workload',*names],rows,'Whole fresh invocation median ms; 10 measured samples per cell')+p('Sum uses assignments, arithmetic, conditions and loops. Function-string defines a callable and changes case/replaces characters. External-100 runs the same absolute /usr/bin/true 100 times. Pipeline uses identical printf/tr executables; Nift uses structured run()/cmd().pipe() capture. The file row executes identical /usr/bin/printf and /usr/bin/cat helpers in all five shells; writing uses POSIX redirection, Nu save or Nift’s file API after structured capture. It measures that mixed orchestration/I/O workflow, not pure native file-read throughput. Equivalent output does not imply identical internal architecture.')
 work+=p('Bash’s trivial invocation was '+f(r('bash',metric='trivial-command')['median_ms'])+' ms versus Nift’s '+f(r('nift',metric='trivial-command')['median_ms'])+' ms. Fish’s external-100 median was '+f(r('fish',metric='external-100')['median_ms'])+' ms versus Nift’s '+f(r('nift',metric='external-100')['median_ms'])+' ms. These rows show why prompt latency alone cannot rank shell performance.')
 work+=figure('shell','external-work',names,{'External-100':[r(n,metric='external-100')['median_ms'] for n in names]},'Launching 100 external commands','Whole invocation median (ms)')
 work+=table(['Shell','Trivial RSS MiB'],[[s,f(r(s,metric='trivial-command')['median_peak_rss_kib']/1024)] for s in names],'Median Linux waited-child high-water RSS; not simultaneous aggregate tree RSS')+p('PTY RSS is omitted because prompt timing stops before oracle/teardown accounting. Concurrent-job, long-pipeline and separate default-dotfile distributions remain coverage gaps; traversal/data work appears in scripting.')
 cal=raw_active('shell','calibration.json')
 assert all(r['correct'] for j in cal['jobs'] for r in j['samples'])
 cert=raw_active('shell','rc-certification.json');assert cert['all_state_valid'] and all(j['correct'] for j in cert['cases'])
 body=raw_active('shell','rc-body.json');assert all(r['correct'] for j in body['jobs'] for r in j['samples'])
 rc_body_table=table(['Diagnostic','User RC body median ms','Min–max ms'],[[j['id'],f(j['median_rc_body_ms']),f(j['min_rc_body_ms'])+'–'+f(j['max_rc_body_ms'])] for j in body['jobs']],'50 native-clock RC-body observations per Bash/Zsh level; not startup-subtracted')
 cal_rows=[[j['id'],f(j['summary']['median_ms']),f(j['summary']['p95_ms'])] for j in cal['jobs']]
 method=table(['Calibration','Median ms','p95 ms'],cal_rows,'50 process/PTY baseline probes per cell; never subtracted')+p('The compiled PTY bridge avoids Python heap fork latency. Minimal probe measurements disclose remaining launch/forwarding/scheduling overhead; differences near that floor need care. Initial Python-PTY series are retained as diagnostics and excluded by a documented method revision, not by selective sample removal.')+rc_body_table+p('Independent Bash/Zsh EPOCHREALTIME clocks instrument synthetic user RC source/parse/execute only, excluding system RC. Clock/read overhead remains; other shells do not have an equivalent timer/parser boundary in this diagnostic. No cross-shell RC-body ranking or subtraction is used. Separate complete-state certification checks every variable and function plus the conditional and PATH prefix in all 18 light/moderate login/non-login cases.')+p('Non-interactive invocations must exit successfully and yield expected output. PTY timing ends at prompt arrival, followed by its command/state oracle; the bridge then terminates the child process group, so a natural-exit status and teardown RSS are outside that boundary. Failures retain non-publishable evidence. Prepared startup cells contain 100 samples; fresh-state startup cells contain 30; both have 3 retained warmups. Configured fresh Zsh rebuilds system completion state, so its expensive series uses 30 samples, frozen before collection. No sample was excluded. Work cells contain 10 plus 3. Order rotates each round.')+p('An allowlisted environment and job-specific HOME/XDG/ZDOTDIR prevent BASH_ENV, ENV, inherited functions, personal dotfiles or tokens from entering measured processes. Terminal queries receive documented xterm responses. OSC 133 prompt completion is used where available, otherwise prompt suffix detection; the oracle proves the shell is usable afterwards. This terminal model affects interactive startup and limits generalisation.')+p('Configuration discovery, parsing, history and lazy initialization can interact. No additive RC decomposition is justified. Rich runtime features and low bare startup answer different engineering questions.')
 write('shell',hero+section('Startup / distributions','A median does not show every stall.',result,'results')+section('Configuration is a variable','Bare → Empty → Light → Moderate',rc,'rc')+section('Orchestration &amp; native work','The shell has work to do.',work)+section('Correctness / limits','Fast and wrong does not qualify.',method,'method')+machine(d,'shell')+evidence('shell',['shell-repeated.json','shell-application-cold.json','calibration.json','rc-certification.json','rc-body.json'],'shell-benchmark','python3 scripts/benchmark.py --nift /opt/campaign/tools/bin/nift --samples 100 --work-samples 10 --warmups 3 --output results/run.json\n# Fresh-state run: --state application-cold --samples 30 --work-samples 10 --warmups 3.')+section('Conclusion','Direct startup evidence, with its boundaries.',p('This matrix is defensible for the exact invocation/configuration paths and small workloads reported. It does not establish a universally fastest shell, feature parity, or machine-cold performance.')))
def scripting():
 d=load_active('scripting','scripting.json');groups={};names=tuple(d['tools'])
 for j in d['jobs']:
  family,size,lang=j['id'].rsplit('/',2);groups.setdefault((family,size),{})[lang]=j
 hero='<section class="hero"><div><p class="eyebrow">Experiment 01 / runtime &amp; scripting</p><h1>One runtime.<br>Different kinds<br>of work.</h1>'+p('What does Nift cost as a scripting language? Separate startup-sensitive snippets from sustained computation and practical file/data work, then compare idiomatic implementations.')+'</div><aside class="trace" aria-label="Measurement flow"><span><b>01</b> source + fixture</span><span><b>02</b> fresh runtime</span><span><b>03</b> output oracle</span><span><b>04</b> retained sample</span><span><b>05</b> run-specific median</span></aside></section>'
 lanes='<div class="lanes">'+''.join(f'<div class="lane"><span class="lane-label">{label}</span><p>{desc}</p></div>' for label,desc in [('STARTUP','No-op/output mainly expose invocation cost. Tiny snippets are not application throughput.'),('COMPUTE','Loops, calls, arrays, map/set, Fibonacci and grid BFS exercise interpreter/JIT and collection paths.'),('FILES + DATA','JSON reads/parsing, record transformation/traversal and recursive files include actual I/O/helper costs.')])+'</div>'
 selected=('sanity/noop','sanity/loops','sanity/function-calls','arrays-strings-hash/sort-index','graphs-trees-search/bfs','structured-data/json-parse','filesystem/traverse')
 rows=[]
 for family in selected:
  size='small' if family=='sanity/noop' else 'large';g=groups[(family,size)]
  rows.append([family+' / '+size]+[f(g[l]['summary']['median_ms']) if l in g else 'Outside scope' for l in names])
 results=table(['Workload / size',*names],rows,'All participating languages; fresh-process median ms, 10 measured samples per cell')+p('A dash (—) means the implementation was outside scope and deliberately excluded; it is not a zero or a failed measurement. Selected classes are not an overall ranking.')
 for family,size in [('sanity/noop','small'),('sanity/loops','large'),('filesystem/traverse','large')]:
  g=groups[(family,size)];key=family.split('/')[-1]
  results+=figure('scripting',key, list(g),{'Median':[g[l]['summary']['median_ms'] for l in g]},family+' / '+size,'Invocation latency (ms)',log=key!='noop')
 for family in d['families']:
  rows=[[size]+[f(groups[(family,size)][l]['summary']['median_ms']) if l in groups[(family,size)] else 'Outside scope' for l in names] for size in ('small','large')]
  results+='<h3>'+esc(family)+'</h3>'+table(['Size',*names],rows,'Fresh-process median ms; 10 measured samples')
 nv=groups[('sanity/noop','small')]['nift']['summary']['median_ms'];lv=groups[('sanity/loops','large')]['nift']['summary']['median_ms']
 results=p('Nift’s tiny no-op median was '+f(nv)+' ms, while the large arithmetic-loop invocation was '+f(lv)+' ms. Read the latter alongside native/JIT peers below: low invocation cost does not establish sustained execution throughput.')+results
 method=p('Ten measured samples plus two retained warmups per job; serial execution, rotated order, C-supervised fork/exec-to-exit latency and Linux waited-child high-water RSS. Every invocation must exit successfully and match its golden output. Alternate numeric formatting is accepted only when exact finite Decimal values agree; rounded output does not count.')+p('Preparation is outside timing. Every sample creates a fresh runtime process with OS caches uncontrolled. We call this fresh-process-repeated, correcting the old suite’s misleading identical cold/warm labels. Historical runs are not merged.')+'<div class="callout"><strong>Legacy-method boundary.</strong> Before the 20261007-v472 official series, the legacy runner prechecked once, hardcoded timed correctness, included a wrapper and aggregated historical machines. JSON transform v2 constructs Nift records in memory like peers rather than writing/re-reading scratch JSON. These corrections were already present in the previous official series; the current rerun preserves its workload definitions. Legacy-method medians remain separate diagnostics.</div>'
 memory_rows=[[lang,f(groups[('sanity/noop','small')][lang]['summary']['median_peak_rss_kib']/1024),f(groups[('filesystem/traverse','large')][lang]['summary']['median_peak_rss_kib']/1024)] for lang in names]
 results+=table(['Runtime','No-op RSS MiB','Large traversal RSS MiB'],memory_rows,'Memory comparisons across all participating runtimes; median waited-child high-water RSS, not aggregate tree memory')
 interpretation=p('Native/JIT collection mechanisms can earn an advantage in sustained computation; invocation cost matters more for tiny automation. Nift’s integrated file/data functionality may be useful without winning every row. No benchmark here prices maintainability or feature convenience.')+p('Bash is excluded from structured-data, Fibonacci and BFS where unnatural. Its recursive file test uses find/wc; other implementations use native APIs. BFS compares idiomatic queue/distance structures rather than identical internals. JSON parse/traverse include the same fixture read. Helpers remain inside timing.')+p('Frequency-count v2 streams counters consistently; sort-index describes sorting and indexed reads. The misleading two-pointer endpoint test is omitted. Three redundant sanity microbenchmarks and duplicate shell startup are omitted. JSON-mutate duplicated record transformation without proving persistent array mutation. Partial JSON-query and unimplemented SQLite/mixed/breadth families are explicit coverage gaps. More end-to-end practical workflows would strengthen relevance.')
 diagnostic=''
 meta=series_meta('scripting')
 if meta and meta['series']=='20261008-v480':
  check=load(f'history/{meta["series"]}/scripting/same-node-version-diagnostic.json')
  jobs={j['id']:j['summary'] for j in check['jobs']}
  cases=('sanity/noop/small','sanity/loops/large','arrays-strings-hash/frequency-count/large','arrays-strings-hash/sort-index/large','structured-data/json-transform/large')
  rows=[[case,f(jobs[case+'/v4.7.2-source']['median_ms']),f(jobs[case+'/v4.8.0-source']['median_ms'])] for case in cases]
